def from_coding(sequence):
    if type(sequence) is not str or not sequence or any(b not in "ACGT" for b in sequence):
        raise ValueError("DNA não vazio e canônico")
    return sequence.replace("T","U")

assert from_coding("ATGC")=="AUGC"
assert from_coding("ACGTAACC")=="ACGUAACC"
try:
    from_coding("ACN")
except ValueError:
    pass
else:
    raise AssertionError("Base ambígua precisa ser rejeitada neste contrato")
